"""Parsing SQL SELECT statements for minisql."""

from dataclasses import dataclass, field
from typing import Any, List, Optional

from .errors import QueryError
from .lexer import tokenize


# ---------------------------------------------------------------------------
# AST


class Expr:
    """Base class for expressions.

    ``text`` is filled in by the parser with the exact source text of the
    expression.  It is deliberately not part of structural comparisons.
    """


@dataclass
class Literal(Expr):
    value: Any


@dataclass
class Column(Expr):
    name: str
    index: Optional[int] = None


@dataclass
class Star(Expr):
    pass


@dataclass
class Function(Expr):
    name: str
    args: List[Expr] = field(default_factory=list)


@dataclass
class Binary(Expr):
    op: str
    left: Expr
    right: Expr


@dataclass
class Unary(Expr):
    op: str
    operand: Expr


@dataclass
class NotExpr(Expr):
    operand: Expr


@dataclass
class IsNull(Expr):
    operand: Expr
    negate: bool = False


@dataclass
class InExpr(Expr):
    operand: Expr
    items: List[Expr] = field(default_factory=list)
    negate: bool = False


@dataclass
class BetweenExpr(Expr):
    operand: Expr
    low: Expr
    high: Expr
    negate: bool = False


@dataclass
class LikeExpr(Expr):
    operand: Expr
    pattern: Expr
    negate: bool = False


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str] = None
    name: str = ""


@dataclass
class OrderItem:
    expr: Expr
    descending: bool = False
    output_index: Optional[int] = None


@dataclass
class Query:
    distinct: bool
    select_star: bool
    select_items: List[SelectItem]
    table: str
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


# ---------------------------------------------------------------------------
# Parser


class Parser:
    def __init__(self, sql, tokens):
        self.sql = sql
        self.tokens = tokens
        self.pos = 0

    @property
    def current(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def advance(self):
        token = self.current
        self.pos += 1
        return token

    def check_keyword(self, word):
        token = self.current
        return token.kind == "KEYWORD" and token.value == word

    def match_keyword(self, word):
        if self.check_keyword(word):
            self.pos += 1
            return True
        return False

    def expect_keyword(self, word):
        if not self.match_keyword(word):
            self.error("expected %s" % word)
        return self.tokens[self.pos - 1]

    def check_op(self, value):
        token = self.current
        return token.kind == "OP" and token.value == value

    def match_op(self, value):
        if self.check_op(value):
            self.pos += 1
            return True
        return False

    def expect_op(self, value):
        if not self.match_op(value):
            self.error("expected %r" % value)
        return self.tokens[self.pos - 1]

    def expect_name(self):
        token = self.current
        if token.kind != "NAME":
            self.error("expected a name")
        self.pos += 1
        return token

    def expect_integer(self):
        token = self.current
        if token.kind != "NUMBER" or not token.value.isdigit():
            self.error("expected an integer")
        self.pos += 1
        return int(token.value)

    def error(self, message):
        token = self.current
        if token.kind == "EOF":
            where = "at end of query"
        else:
            where = "near %r" % self.sql[token.pos:token.end]
        raise QueryError("%s %s" % (message, where))

    # -- statements ---------------------------------------------------------

    def parse_query(self):
        self.expect_keyword("SELECT")
        distinct = self.match_keyword("DISTINCT")

        select_star = False
        select_items = []
        if self.check_op("*"):
            self.advance()
            select_star = True
        else:
            select_items.append(self.parse_select_item())
            while self.match_op(","):
                select_items.append(self.parse_select_item())

        self.expect_keyword("FROM")
        table = self.expect_name().value

        where = None
        if self.match_keyword("WHERE"):
            where = self.parse_expression()

        group_by = []
        if self.match_keyword("GROUP"):
            self.expect_keyword("BY")
            group_by.append(self.parse_expression())
            while self.match_op(","):
                group_by.append(self.parse_expression())

        having = None
        if self.match_keyword("HAVING"):
            having = self.parse_expression()

        order_by = []
        if self.match_keyword("ORDER"):
            self.expect_keyword("BY")
            order_by.append(self.parse_order_item())
            while self.match_op(","):
                order_by.append(self.parse_order_item())

        limit = None
        offset = None
        if self.match_keyword("LIMIT"):
            limit = self.expect_integer()
            if self.match_keyword("OFFSET"):
                offset = self.expect_integer()

        self.match_op(";")

        if self.current.kind != "EOF":
            self.error("unexpected input")

        return Query(
            distinct=distinct,
            select_star=select_star,
            select_items=select_items,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def parse_select_item(self):
        expr = self.parse_expression()
        alias = None
        if self.match_keyword("AS"):
            alias = self.expect_name().value
        elif self.current.kind == "NAME":
            alias = self.advance().value
        return SelectItem(expr=expr, alias=alias)

    def parse_order_item(self):
        expr = self.parse_expression()
        descending = False
        if self.match_keyword("ASC"):
            descending = False
        elif self.match_keyword("DESC"):
            descending = True
        return OrderItem(expr=expr, descending=descending)

    # -- expressions --------------------------------------------------------

    def parse_expression(self):
        start = self.current.pos
        expr = self.parse_or()
        end = self.tokens[self.pos - 1].end
        expr.text = self.sql[start:end]
        return expr

    def parse_or(self):
        left = self.parse_and()
        while self.match_keyword("OR"):
            right = self.parse_and()
            left = Binary("OR", left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.match_keyword("AND"):
            right = self.parse_not()
            left = Binary("AND", left, right)
        return left

    def parse_not(self):
        if self.match_keyword("NOT"):
            return NotExpr(self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()

        if self.match_keyword("IS"):
            negate = self.match_keyword("NOT")
            self.expect_keyword("NULL")
            return IsNull(left, negate=negate)

        negate = False
        if self.check_keyword("NOT") and self.peek().kind == "KEYWORD" and \
                self.peek().value in ("IN", "BETWEEN", "LIKE"):
            self.advance()
            negate = True

        if self.match_keyword("IN"):
            self.expect_op("(")
            items = []
            if not self.check_op(")"):
                items.append(self.parse_expression())
                while self.match_op(","):
                    items.append(self.parse_expression())
            self.expect_op(")")
            return InExpr(left, items, negate=negate)

        if self.match_keyword("BETWEEN"):
            low = self.parse_additive()
            self.expect_keyword("AND")
            high = self.parse_additive()
            return BetweenExpr(left, low, high, negate=negate)

        if self.match_keyword("LIKE"):
            pattern = self.parse_additive()
            return LikeExpr(left, pattern, negate=negate)

        if negate:
            self.error("expected IN, BETWEEN, or LIKE after NOT")

        token = self.current
        if token.kind == "OP" and token.value in ("=", "!=", "<>", "<", "<=", ">", ">="):
            op = self.advance().value
            if op == "<>":
                op = "!="
            right = self.parse_additive()
            return Binary(op, left, right)

        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while True:
            if self.match_op("+"):
                left = Binary("+", left, self.parse_multiplicative())
            elif self.match_op("-"):
                left = Binary("-", left, self.parse_multiplicative())
            elif self.match_op("||"):
                left = Binary("||", left, self.parse_multiplicative())
            else:
                break
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while True:
            if self.match_op("*"):
                left = Binary("*", left, self.parse_unary())
            elif self.match_op("/"):
                left = Binary("/", left, self.parse_unary())
            else:
                break
        return left

    def parse_unary(self):
        if self.match_op("-"):
            return Unary("-", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        token = self.current

        if token.kind == "NUMBER":
            self.advance()
            if "." in token.value:
                value = float(token.value)
            else:
                value = int(token.value)
            return Literal(value)

        if token.kind == "STRING":
            self.advance()
            return Literal(token.value)

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self.advance()
                return Literal(None)
            if token.value == "TRUE":
                self.advance()
                return Literal(True)
            if token.value == "FALSE":
                self.advance()
                return Literal(False)
            self.error("expected an expression")

        if token.kind == "NAME":
            self.advance()
            if not token.quoted and self.check_op("("):
                self.advance()
                args = []
                if self.check_op("*"):
                    self.advance()
                    args.append(Star())
                    self.expect_op(")")
                else:
                    if not self.check_op(")"):
                        args.append(self.parse_expression())
                        while self.match_op(","):
                            args.append(self.parse_expression())
                    self.expect_op(")")
                return Function(token.value, args)
            return Column(token.value)

        if self.match_op("("):
            expr = self.parse_expression()
            self.expect_op(")")
            return expr

        self.error("expected an expression")

    # -- source text of AST nodes ------------------------------------------

    def parse(self):
        return self.parse_query()


def parse(sql):
    """Parse ``sql`` and return a :class:`Query`."""
    return Parser(sql, tokenize(sql)).parse_query()

