"""Planning and evaluating minisql queries."""

import csv
import math
import os
import re
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation, localcontext
from functools import cmp_to_key
from typing import Any, List, Optional

from .errors import QueryError
from .parser import (
    BetweenExpr,
    Binary,
    Column,
    Expr,
    Function,
    InExpr,
    IsNull,
    LikeExpr,
    Literal,
    NotExpr,
    OrderItem,
    Query,
    SelectItem,
    Star,
    Unary,
    parse,
)


AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}

SCALAR_ARITY = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (2, None),
}

_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"(?:-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+)\Z")


@dataclass
class Result:
    """The result of running a query."""

    columns: List[str]
    rows: List[tuple]


@dataclass
class _Table:
    columns: List[str]
    rows: List[tuple]


@dataclass
class _Group:
    rows: List[tuple]
    values: tuple


@dataclass
class _Record:
    values: tuple
    keys: List[Any]


class _RowContext:
    def __init__(self, row):
        self.row = row


class _GroupContext:
    def __init__(self, group, key_index):
        self.group = group
        self.key_index = key_index


# ---------------------------------------------------------------------------
# Helpers


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _category(value):
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return "unknown"


def _norm_value(value):
    """A hashable value used for grouping and DISTINCT."""
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("boolean", value)
    if isinstance(value, (int, float)):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    return ("unknown", repr(value))


def _expr_key(expr):
    """A structural key for an expression, ignoring its source text."""
    if isinstance(expr, Literal):
        value = expr.value
        if value is None:
            return ("literal", "null")
        if isinstance(value, bool):
            return ("literal", "boolean", value)
        if isinstance(value, int):
            return ("literal", "integer", value)
        if isinstance(value, float):
            return ("literal", "number", value)
        if isinstance(value, str):
            return ("literal", "string", value)
        return ("literal", repr(value))
    if isinstance(expr, Column):
        if expr.index is not None:
            return ("column", expr.index)
        return ("column-name", expr.name.casefold())
    if isinstance(expr, Star):
        return ("star",)
    if isinstance(expr, Function):
        return ("function", expr.name.upper(), tuple(_expr_key(a) for a in expr.args))
    if isinstance(expr, Binary):
        return ("binary", expr.op, _expr_key(expr.left), _expr_key(expr.right))
    if isinstance(expr, Unary):
        return ("unary", expr.op, _expr_key(expr.operand))
    if isinstance(expr, NotExpr):
        return ("not", _expr_key(expr.operand))
    if isinstance(expr, IsNull):
        return ("is-null", _expr_key(expr.operand), expr.negate)
    if isinstance(expr, InExpr):
        return ("in", _expr_key(expr.operand), tuple(_expr_key(i) for i in expr.items), expr.negate)
    if isinstance(expr, BetweenExpr):
        return ("between", _expr_key(expr.operand), _expr_key(expr.low),
                _expr_key(expr.high), expr.negate)
    if isinstance(expr, LikeExpr):
        return ("like", _expr_key(expr.operand), _expr_key(expr.pattern), expr.negate)
    raise QueryError("internal error: unknown expression")


def _children(expr):
    if isinstance(expr, Function):
        return list(expr.args)
    if isinstance(expr, Binary):
        return [expr.left, expr.right]
    if isinstance(expr, Unary):
        return [expr.operand]
    if isinstance(expr, NotExpr):
        return [expr.operand]
    if isinstance(expr, IsNull):
        return [expr.operand]
    if isinstance(expr, InExpr):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, BetweenExpr):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, LikeExpr):
        return [expr.operand, expr.pattern]
    return []


def _contains_aggregate(expr):
    if isinstance(expr, Function) and expr.name.upper() in AGGREGATES:
        return True
    return any(_contains_aggregate(child) for child in _children(expr))


def _convert_field(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(name, directory):
    path = os.path.join(os.fspath(directory), name + ".csv")
    try:
        with open(path, "r", newline="", encoding="utf-8") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table %r is empty" % name)

            rows = []
            for fields in reader:
                if len(fields) == 0:
                    # Ignore completely blank lines.
                    continue
                if len(fields) != len(header):
                    raise QueryError(
                        "table %r has a row with %d fields, expected %d"
                        % (name, len(fields), len(header))
                    )
                rows.append(tuple(_convert_field(field) for field in fields))
    except FileNotFoundError:
        raise QueryError("table %r not found" % name)
    except OSError as exc:
        raise QueryError("could not read table %r: %s" % (name, exc))
    except csv.Error as exc:
        raise QueryError("could not parse table %r: %s" % (name, exc))

    return _Table(header, rows)


def _format_number_round(value):
    if isinstance(value, int):
        return value
    if value >= 0:
        return int(math.floor(value + 0.5))
    return -int(math.floor(-value + 0.5))


def _round_places(value, places):
    number = Decimal(str(value))
    quantum = Decimal(1).scaleb(-places)
    try:
        with localcontext() as context:
            context.prec = max(28, len(number.as_tuple().digits) + abs(places) + 5)
            rounded = number.quantize(quantum, rounding=ROUND_HALF_UP)
    except InvalidOperation:
        raise QueryError("cannot round %r to %d decimal places" % (value, places))
    return float(rounded)


def _like_regex(pattern):
    pieces = []
    for char in pattern:
        if char == "%":
            pieces.append(".*")
        elif char == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(char))
    return re.compile(r"\A" + "".join(pieces) + r"\Z", re.DOTALL)


# ---------------------------------------------------------------------------
# Planner


class Planner:
    def __init__(self, query, directory):
        self.query = query
        self.table = _load_table(query.table, directory)
        self.header_index = {}
        for index, name in enumerate(self.table.columns):
            self.header_index.setdefault(name.casefold(), index)

        self.select_items = self._expand_select()
        self._resolve_columns_everywhere()
        self._set_output_names()
        self._resolve_order_items()

        self._validate_functions(self.query.where, False, "WHERE")
        for item in self.select_items:
            self._validate_functions(item.expr, True, "SELECT")
        for expr in self.query.group_by:
            self._validate_functions(expr, False, "GROUP BY")
        self._validate_functions(self.query.having, True, "HAVING")
        for item in self.query.order_by:
            if item.output_index is None:
                self._validate_functions(item.expr, True, "ORDER BY")

        has_aggregate = any(_contains_aggregate(item.expr) for item in self.select_items)
        if self.query.having is not None:
            has_aggregate = has_aggregate or _contains_aggregate(self.query.having)
        for item in self.query.order_by:
            if item.output_index is None:
                has_aggregate = has_aggregate or _contains_aggregate(item.expr)

        self.grouped = bool(self.query.group_by) or has_aggregate
        self.group_key_index = {}
        for index, expr in enumerate(self.query.group_by):
            self.group_key_index.setdefault(_expr_key(expr), index)

        if self.grouped:
            self._validate_grouped_query()

    # -- select list --------------------------------------------------------

    def _expand_select(self):
        if not self.query.select_star:
            return list(self.query.select_items)

        items = []
        for index, name in enumerate(self.table.columns):
            expr = Column(name)
            expr.index = index
            expr.text = name
            items.append(SelectItem(expr=expr))
        return items

    # -- resolution ---------------------------------------------------------

    def _resolve_column(self, expr):
        if isinstance(expr, Column):
            index = self.header_index.get(expr.name.casefold())
            if index is None:
                raise QueryError("unknown column %r" % expr.name)
            expr.index = index
            return
        for child in _children(expr):
            self._resolve_column(child)

    def _resolve_columns_everywhere(self):
        if self.query.where is not None:
            self._resolve_column(self.query.where)
        for item in self.select_items:
            self._resolve_column(item.expr)
        for expr in self.query.group_by:
            self._resolve_column(expr)
        if self.query.having is not None:
            self._resolve_column(self.query.having)

    def _set_output_names(self):
        for item in self.select_items:
            if item.alias is not None:
                item.name = item.alias
            elif isinstance(item.expr, Column):
                item.name = self.table.columns[item.expr.index]
            else:
                item.name = item.expr.text

    def _resolve_order_items(self):
        for item in self.query.order_by:
            expr = item.expr

            if isinstance(expr, Literal) and type(expr.value) is int:
                position = expr.value
                if position < 1 or position > len(self.select_items):
                    raise QueryError("ORDER BY position %d is out of range" % position)
                item.output_index = position - 1
                continue

            if isinstance(expr, Column):
                for index, selected in enumerate(self.select_items):
                    if selected.name.casefold() == expr.name.casefold():
                        item.output_index = index
                        break
                if item.output_index is not None:
                    continue

            self._resolve_column(expr)

    # -- function validation ------------------------------------------------

    def _validate_functions(self, expr, allow_aggregate, clause):
        if expr is None:
            return
        if isinstance(expr, Star):
            raise QueryError("'*' is only allowed in COUNT(*)")

        if isinstance(expr, Function):
            name = expr.name.upper()
            if name in AGGREGATES:
                if not allow_aggregate:
                    raise QueryError("aggregate %s is not allowed in %s" % (name, clause))
                self._check_arity(expr, name)
                for arg in expr.args:
                    if isinstance(arg, Star) and name != "COUNT":
                        raise QueryError("'*' is only allowed in COUNT(*)")
                    self._validate_functions(arg, False, clause)
                return

            if name not in SCALAR_ARITY:
                raise QueryError("unknown function %r" % expr.name)
            self._check_arity(expr, name)
            for arg in expr.args:
                self._validate_functions(arg, allow_aggregate, clause)
            return

        for child in _children(expr):
            self._validate_functions(child, allow_aggregate, clause)

    def _check_arity(self, expr, name):
        if name in AGGREGATES:
            low, high = 1, 1
        else:
            low, high = SCALAR_ARITY[name]
        count = len(expr.args)
        if count < low or (high is not None and count > high):
            raise QueryError("wrong number of arguments to %s" % expr.name)

    # -- grouping validation ------------------------------------------------

    def _validate_grouped_query(self):
        for item in self.select_items:
            self._validate_grouped_expr(item.expr)
        if self.query.having is not None:
            self._validate_grouped_expr(self.query.having)
        for item in self.query.order_by:
            if item.output_index is None:
                self._validate_grouped_expr(item.expr)

    def _validate_grouped_expr(self, expr):
        if _expr_key(expr) in self.group_key_index:
            return
        if isinstance(expr, Function) and expr.name.upper() in AGGREGATES:
            return
        if isinstance(expr, Column):
            raise QueryError(
                "column %r must appear in GROUP BY or be used in an aggregate"
                % expr.name
            )
        for child in _children(expr):
            self._validate_grouped_expr(child)

    # -- execution ----------------------------------------------------------

    def execute(self):
        rows = self.table.rows

        if self.query.where is not None:
            rows = [row for row in rows
                    if self._eval(self.query.where, _RowContext(row)) is True]

        if self.grouped:
            units = self._make_groups(rows)
        else:
            units = rows

        if self.query.having is not None:
            if self.grouped:
                units = [group for group in units
                         if self._eval(self.query.having, self._group_context(group)) is True]
            else:
                units = [row for row in units
                         if self._eval(self.query.having, _RowContext(row)) is True]

        records = []
        for unit in units:
            if self.grouped:
                context = self._group_context(unit)
            else:
                context = _RowContext(unit)

            values = tuple(self._eval(item.expr, context) for item in self.select_items)
            keys = []
            for item in self.query.order_by:
                if item.output_index is not None:
                    keys.append(values[item.output_index])
                else:
                    keys.append(self._eval(item.expr, context))
            records.append(_Record(values, keys))

        if self.query.distinct:
            seen = set()
            distinct_records = []
            for record in records:
                key = tuple(_norm_value(value) for value in record.values)
                if key not in seen:
                    seen.add(key)
                    distinct_records.append(record)
            records = distinct_records

        if self.query.order_by:
            order_items = self.query.order_by

            def compare(left, right):
                for index, item in enumerate(order_items):
                    result = self._compare_order(left.keys[index], right.keys[index])
                    if result:
                        return -result if item.descending else result
                return 0

            records.sort(key=cmp_to_key(compare))

        start = self.query.offset or 0
        if self.query.limit is not None:
            records = records[start:start + self.query.limit]
        elif start:
            records = records[start:]

        return Result(
            columns=[item.name for item in self.select_items],
            rows=[record.values for record in records],
        )

    def _make_groups(self, rows):
        if not self.query.group_by:
            return [_Group(rows, ())]

        groups = []
        seen = {}
        for row in rows:
            context = _RowContext(row)
            values = tuple(self._eval(expr, context) for expr in self.query.group_by)
            key = tuple(_norm_value(value) for value in values)
            if key in seen:
                groups[seen[key]].rows.append(row)
            else:
                seen[key] = len(groups)
                groups.append(_Group([row], values))
        return groups

    def _group_context(self, group):
        return _GroupContext(group, self.group_key_index)

    # -- expression evaluation ---------------------------------------------

    def _eval(self, expr, context):
        if isinstance(context, _GroupContext):
            index = context.key_index.get(_expr_key(expr))
            if index is not None:
                return context.group.values[index]

        if isinstance(expr, Literal):
            return expr.value
        if isinstance(expr, Column):
            if isinstance(context, _RowContext):
                return context.row[expr.index]
            raise QueryError(
                "column %r must appear in GROUP BY or be used in an aggregate"
                % expr.name
            )
        if isinstance(expr, Star):
            raise QueryError("'*' is only allowed in COUNT(*)")

        if isinstance(expr, Function):
            name = expr.name.upper()
            if name in AGGREGATES:
                if not isinstance(context, _GroupContext):
                    raise QueryError("aggregate %s is not allowed here" % name)
                return self._eval_aggregate(expr, context)
            if name == "COALESCE":
                for arg in expr.args:
                    value = self._eval(arg, context)
                    if value is not None:
                        return value
                return None
            args = [self._eval(arg, context) for arg in expr.args]
            return self._eval_scalar(name, args)

        if isinstance(expr, NotExpr):
            value = self._as_boolean(self._eval(expr.operand, context), "NOT")
            if value is None:
                return None
            return not value

        if isinstance(expr, IsNull):
            value = self._eval(expr.operand, context)
            result = value is None
            return not result if expr.negate else result

        if isinstance(expr, InExpr):
            return self._eval_in(expr, context)

        if isinstance(expr, BetweenExpr):
            return self._eval_between(expr, context)

        if isinstance(expr, LikeExpr):
            return self._eval_like(expr, context)

        if isinstance(expr, Unary):
            value = self._eval(expr.operand, context)
            if value is None:
                return None
            if not _is_number(value):
                raise QueryError("unary - requires a number")
            return -value

        if isinstance(expr, Binary):
            return self._eval_binary(expr, context)

        raise QueryError("internal error: unknown expression")

    def _eval_binary(self, expr, context):
        op = expr.op

        if op in ("AND", "OR"):
            left = self._as_boolean(self._eval(expr.left, context), op)
            if op == "AND" and left is False:
                return False
            if op == "OR" and left is True:
                return True
            right = self._as_boolean(self._eval(expr.right, context), op)
            if op == "AND":
                if right is False:
                    return False
                if left is None or right is None:
                    return None
                return True
            if right is True:
                return True
            if left is None or right is None:
                return None
            return False

        left = self._eval(expr.left, context)
        right = self._eval(expr.right, context)

        if op in ("+", "-", "*", "/"):
            return self._arithmetic(op, left, right)
        if op == "||":
            if left is None or right is None:
                return None
            return self._text(left) + self._text(right)
        return self._compare(op, left, right)

    def _eval_in(self, expr, context):
        value = self._eval(expr.operand, context)
        if value is None:
            return None

        saw_null = False
        matched = False
        for item_expr in expr.items:
            item = self._eval(item_expr, context)
            if item is None:
                saw_null = True
            elif self._compare("=", value, item) is True:
                matched = True
                break

        if matched:
            result = True
        elif saw_null:
            result = None
        else:
            result = False

        if expr.negate:
            if result is None:
                return None
            return not result
        return result

    def _eval_between(self, expr, context):
        value = self._eval(expr.operand, context)
        if value is None:
            return None
        low = self._eval(expr.low, context)
        high = self._eval(expr.high, context)

        first = self._compare("<=", low, value)
        second = self._compare("<=", value, high)
        result = self._and3(first, second)

        if expr.negate:
            if result is None:
                return None
            return not result
        return result

    def _eval_like(self, expr, context):
        value = self._eval(expr.operand, context)
        pattern = self._eval(expr.pattern, context)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError("LIKE requires string operands")
        result = _like_regex(pattern).match(value) is not None
        if expr.negate:
            return not result
        return result

    def _eval_aggregate(self, expr, context):
        name = expr.name.upper()
        argument = expr.args[0]
        if isinstance(argument, Star):
            return len(context.group.rows)

        values = []
        for row in context.group.rows:
            value = self._eval(argument, _RowContext(row))
            if value is not None:
                values.append(value)

        if name == "COUNT":
            return len(values)
        if not values:
            return None

        if name in ("SUM", "AVG"):
            for value in values:
                if not _is_number(value):
                    raise QueryError("%s requires numeric values" % name)
            total = sum(values)
            if name == "AVG":
                return float(total) / len(values)
            if all(isinstance(value, int) for value in values):
                return total
            return float(total)

        if name in ("MIN", "MAX"):
            best = values[0]
            for value in values[1:]:
                result = self._compare_values(best, value)
                if name == "MIN":
                    if result > 0:
                        best = value
                else:
                    if result < 0:
                        best = value
            return best

        raise QueryError("unknown aggregate %r" % expr.name)

    def _eval_scalar(self, name, args):
        if name in ("LOWER", "UPPER", "LENGTH"):
            value = args[0]
            if value is None:
                return None
            if not isinstance(value, str):
                raise QueryError("%s requires a string" % name)
            if name == "LOWER":
                return value.lower()
            if name == "UPPER":
                return value.upper()
            return len(value)

        if name == "ABS":
            value = args[0]
            if value is None:
                return None
            if not _is_number(value):
                raise QueryError("ABS requires a number")
            return abs(value)

        if name == "ROUND":
            value = args[0]
            if value is None:
                return None
            if not _is_number(value):
                raise QueryError("ROUND requires a number")
            if len(args) == 1:
                return _format_number_round(value)
            places = args[1]
            if places is None:
                return None
            if not isinstance(places, int) or isinstance(places, bool):
                raise QueryError("ROUND requires an integer number of places")
            return _round_places(value, places)

        raise QueryError("unknown function %r" % name)

    # -- value operations ---------------------------------------------------

    def _as_boolean(self, value, operator):
        if value is None:
            return None
        if isinstance(value, bool):
            return value
        raise QueryError("%s requires boolean operands" % operator)

    @staticmethod
    def _and3(left, right):
        if left is False or right is False:
            return False
        if left is None or right is None:
            return None
        return True

    @staticmethod
    def _text(value):
        if isinstance(value, str):
            return value
        return str(value)

    @staticmethod
    def _arithmetic(op, left, right):
        if left is None or right is None:
            return None
        if not _is_number(left) or not _is_number(right):
            raise QueryError("arithmetic requires numbers")

        if op == "/":
            if right == 0:
                return None
            return left / right
        if isinstance(left, int) and isinstance(right, int):
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            return left * right

        left = float(left)
        right = float(right)
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        return left * right

    @staticmethod
    def _compare_values(left, right):
        if left is None and right is None:
            return 0
        if left is None:
            return -1
        if right is None:
            return 1

        left_category = _category(left)
        right_category = _category(right)
        if left_category != right_category:
            raise QueryError(
                "cannot compare a %s with a %s"
                % (left_category, right_category)
            )

        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    def _compare(self, op, left, right):
        if left is None or right is None:
            return None

        left_category = _category(left)
        right_category = _category(right)
        if left_category != right_category:
            raise QueryError(
                "cannot compare a %s with a %s"
                % (left_category, right_category)
            )

        if op == "=":
            return left == right
        if op == "!=":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
        raise QueryError("unknown comparison operator %r" % op)

    def _compare_order(self, left, right):
        if left is None and right is None:
            return 0
        if left is None:
            return -1
        if right is None:
            return 1
        return self._compare_values(left, right)


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    query = parse(sql)
    return Planner(query, directory).execute()

