{"content":""""Command line interface: ``python -m minisql QUERY [--dir DIR]``."""

import argparse
import csv
import sys

from . import QueryError, run


def _format(value):
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    return value


def main(argv=None):
    parser = argparse.ArgumentParser(prog="minisql")
    parser.add_argument("query", help="SELECT query to run")
    parser.add_argument("--dir", default=".", help="directory containing CSV files")
    args = parser.parse_args(argv)

    try:
        result = run(args.query, args.dir)
    except QueryError as exc:
        print(exc, file=sys.stderr)
        return 1

    writer = csv.writer(sys.stdout)
    writer.writerow(result.columns)
    for row in result.rows:
        writer.writerow([_format(value) for value in row])
    return 0


if __name__ == "__main__":
    sys.exit(main())
