reader = csv.reader(handle)
try:
    header = next(reader)
except StopIteration:
    raise QueryError("table %r is empty" % name)
if len(header) == 0:
    # A blank first line is a single unnamed column.
    header = [""]

rows = []
for fields in reader:
    if len(fields) == 0:
        # csv.reader reports a blank line as no fields.  In a
        # one-column file such a line is a row containing NULL.
        if len(header) == 1:
            rows.append((None,))
        continue
    if len(fields) != len(header):
        raise QueryError(
            "table %r has a row with %d fields, expected %d"
            % (name, len(fields), len(header))
        )
    rows.append(tuple(_convert_field(field) for field in fields))

